import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"卸载平台","description":"在终端确认卸载范围，选择保留平台数据或删除数据，并核对卸载结果。","frontmatter":{"title":"卸载平台","description":"在终端确认卸载范围，选择保留平台数据或删除数据，并核对卸载结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/uninstall.md","filePath":"zh/安装运维/卸载平台.md"}'),h={name:"zh/installation/uninstall.md"};function i(o,t,l,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="卸载平台" tabindex="-1">卸载平台 <a class="header-anchor" href="#卸载平台" aria-label="Permalink to &quot;卸载平台&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>按已确认的停用计划卸载 InduFrame 中心，并明确哪些数据需要保留、哪些内容允许删除。</p><h2 id="角色与环境前提" tabindex="-1">角色与环境前提 <a class="header-anchor" href="#角色与环境前提" aria-label="Permalink to &quot;角色与环境前提&quot;">​</a></h2><p>由具备服务器系统管理权限的维护人员执行。开始前通知使用者，安排停止使用，并确认当前服务器和平台就是本次卸载对象。</p><ul><li>计划保留数据重新安装时，先准备<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>所需的原服务器、原数据卷、完整原安装包和原账号。</li><li>计划删除数据时，先由数据负责人确认删除范围。需要保留的信息须完成备份并确认可恢复；当前安装包不提供一键完整备份恢复工具。</li></ul><p>保留数据卸载会停止平台服务，用户将无法继续访问平台。</p><h2 id="操作入口" tabindex="-1">操作入口 <a class="header-anchor" href="#操作入口" aria-label="Permalink to &quot;操作入口&quot;">​</a></h2><p>安装成功后，卸载程序保存在实际程序目录中。默认安装位置可在服务器交互终端执行以下命令。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/induframe/uninstall.sh</span></span></code></pre></div><p>使用自定义存放位置时，将路径替换为该父目录下的 <code>induframe/uninstall.sh</code>。卸载不需要额外参数。即使原安装包已被移走，也应使用实际程序目录中保留的卸载入口。</p><h2 id="卸载步骤与确认字段" tabindex="-1">卸载步骤与确认字段 <a class="header-anchor" href="#卸载步骤与确认字段" aria-label="Permalink to &quot;卸载步骤与确认字段&quot;">​</a></h2><h3 id="_1-记录日志位置" tabindex="-1">1. 记录日志位置 <a class="header-anchor" href="#_1-记录日志位置" aria-label="Permalink to &quot;1. 记录日志位置&quot;">​</a></h3><p>启动后，终端会显示“详细输出”及本次卸载日志路径。记录该路径，随后按提示确认。</p><p>卸载必须在可以交互回答的终端中执行。没有可用终端时，卸载会拒绝执行并提示未做任何改动。</p><h3 id="_2-确认是否开始卸载" tabindex="-1">2. 确认是否开始卸载 <a class="header-anchor" href="#_2-确认是否开始卸载" aria-label="Permalink to &quot;2. 确认是否开始卸载&quot;">​</a></h3><p>终端询问“确定卸载 InduFrame 中心？”并显示 <code>[y/N]</code>。</p><table tabindex="0"><thead><tr><th>回答</th><th>结果</th></tr></thead><tbody><tr><td><code>n</code> 或直接回车</td><td>取消卸载，不进入后续停服务步骤</td></tr><tr><td><code>y</code></td><td>继续询问数据处理方式，此时尚未开始删除</td></tr></tbody></table><h3 id="_3-选择数据处理方式" tabindex="-1">3. 选择数据处理方式 <a class="header-anchor" href="#_3-选择数据处理方式" aria-label="Permalink to &quot;3. 选择数据处理方式&quot;">​</a></h3><p>终端询问“是否同时删除平台数据与运行环境（数据库、对象库、配置、日志、程序目录）？”并显示 <code>[y/N]</code>。</p><table tabindex="0"><thead><tr><th>回答</th><th>结果</th></tr></thead><tbody><tr><td><code>n</code> 或直接回车</td><td><strong>执行保留数据卸载</strong>：停止平台服务，保留原有平台数据及后续重新安装所需的资料</td></tr><tr><td><code>y</code></td><td>进入删除数据的最终确认</td></tr></tbody></table><p>注意两次回车的含义不同：第一次询问时回车是取消；已经确认卸载后，第二次询问时回车会真正卸载服务并保留数据。</p><h3 id="_4-仅删除数据时-完成最终确认" tabindex="-1">4. 仅删除数据时，完成最终确认 <a class="header-anchor" href="#_4-仅删除数据时-完成最终确认" aria-label="Permalink to &quot;4. 仅删除数据时，完成最终确认&quot;">​</a></h3><p>选择删除数据后，终端提示删除的数据无法恢复，并要求“输入 PURGE 确认”。只有输入完全一致的大写 <code>PURGE</code> 才继续；输入其他内容或直接回车会取消本次卸载。</p><p>如果服务器在安装平台前已有运行环境，终端还会询问是否连它一起删除，并提醒其中其他服务和数据也会消失。默认保留；不了解其用途时，不要同意删除。</p><p>阅读终端列出的删除范围后，等待卸载结束。</p><h2 id="两种方式分别保留什么" tabindex="-1">两种方式分别保留什么 <a class="header-anchor" href="#两种方式分别保留什么" aria-label="Permalink to &quot;两种方式分别保留什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>处理范围</th></tr></thead><tbody><tr><td>保留数据卸载</td><td>停止平台服务，保留原数据库、对象、源码与依赖等数据，以及重新连接原数据所需的凭据和记录；保留服务器运行环境</td></tr><tr><td>删除数据卸载</td><td>按确认范围删除本平台服务与数据、配置与状态、程序目录与日志、平台程序，以及由本安装器添加的运行环境和系统账号等内容</td></tr></tbody></table><p>保留数据卸载仍会清理部分安装配置，重新安装时需要再次填写向导；使用自签名证书时会重新生成证书。保留数据不等于所有安装设置原样不动。</p><p>无论是否选择删除数据，<strong>待核对的采集数据都可能单独留存</strong>，不随本次清理删除。终端若报告采集留存目录，请记录并交给维护人员核对后处理。工程计算使用的系统级隔离规则也不由卸载自动清除，需要维护人员另行核对。不要把删除数据的完成提示理解为服务器上所有相关内容均已清空。</p><h2 id="成功确认" tabindex="-1">成功确认 <a class="header-anchor" href="#成功确认" aria-label="Permalink to &quot;成功确认&quot;">​</a></h2><p>根据选择核对最终结果。</p><table tabindex="0"><thead><tr><th>选择</th><th>应确认的结果</th></tr></thead><tbody><tr><td>取消</td><td>终端显示已取消；不要将取消当作卸载完成</td></tr><tr><td>保留数据卸载</td><td>终端明确显示服务已卸载、数据等内容已保留，平台入口停止服务</td></tr><tr><td>删除数据卸载</td><td>终端明确显示所选服务和数据已删除，并说明原有运行环境是否保留</td></tr></tbody></table><p>出现停止失败、留存失败或清理未完成的提示时，不能仅凭页面打不开就认定卸载成功。</p><h2 id="未能完成时" tabindex="-1">未能完成时 <a class="header-anchor" href="#未能完成时" aria-label="Permalink to &quot;未能完成时&quot;">​</a></h2><p>保留终端输出和卸载日志，停止后续手工清理，并联系维护人员。不要强行删除数据目录、安装记录或剩余文件，也不要立即开始重新安装。</p><p>维护人员应先确认服务停止情况、原数据状态和本次已执行的范围。相关现象见<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>保留数据卸载成功后，需要恢复使用时继续<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>。删除数据后，由维护人员处理已报告的留存事项；需要全新安装时，从<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>重新开始。</p>',39)])])}const b=a(h,[["render",i]]);export{u as __pageData,b as default};
